mapper.update:
update user set

        username = #{username}


        ,password = #{password}


        ,image = #{image}


        ,email = #{email}


        ,type = #{type}


        ,last_study_day = #{lastStudyDay}


        ,study_days = #{studyDays}


        ,total_study_days = #{totalStudyDays}


        ,dark_mode = #{darkMode}

    where id = #{id}
